   "orig": "Colle: impresa sviluppa e innova Paese",
   "lead": "Il presidente della Repubblica Sergio Mattarella ha inviato un messaggio a Confesercenti in cui sottolinea il ruolo dell'impresa nello sviluppo e nell'innovazione del Paese. Il messaggio è stato indirizzato in occasione di un appuntamento dell'associazione di categoria. Lo riferisce Rai News.",
