   "orig": "La mappa di Lucca Comics & Games 2026",
   "lead": "L'organizzazione di Lucca Comics & Games ha pubblicato online la mappa dell'edizione 2026 della manifestazione. La mappa mostra i padiglioni dedicati agli editori, quelli riservati ai giochi, i luoghi di interesse e le location dove si svolgeranno gli eventi principali della kermesse. Lo riferisce Fumettologica.",
