   "sez": "sport",
   "titolo": "Inter in crisi in Champions: 7 sconfitte nelle ultime 8 gare, Chivu avverte la squadra",
   "orig": "L’Inter ha il mal di Champions, perse 7 delle ultime 8 gare. Chivu: “Se vai piano in Europa crolli ”",
   "lead": "Dopo la sconfitta per 4-3 contro il Bruges, l'allenatore dell'Inter Cristian Chivu ha analizzato la crisi europea della sua squadra, che ha perso 7 delle ultime 8 partite in Champions League subendo 19 reti. Chivu ha dichiarato che in questa competizione ogni errore si paga e ha indicato nella mancanza di lucidità, equilibrio e intensità i problemi principali dei nerazzurri. L'ex tecnico Fabio Capello ha definito preoccupante la situazione fisica della squadra, parlando di un'Inter che ha giocato sotto ritmo e evidenziando fragilità difensive viste in campo.",
   "more": [
    "La Champions League è la massima competizione calcistica europea per club. L'Inter, una delle squadre italiane di maggior tradizione, è stata finalista nelle ultime edizioni ma sta attraversando un periodo difficile proprio nella competizione continentale, nonostante un rendimento diverso in campionato."
   ],
