   "titolo": "Australia, i Verdi bloccano il taglio ai rimborsi sanitari privati per gli anziani",
   "orig": "Labor’s bill to cut private health insurance rebate blocked by Greens over pensioner carve-out",
   "lead": "La proposta del governo laburista australiano di tagliare il rimborso per le assicurazioni sanitarie private destinate agli over 65 è stata bloccata in Parlamento dai Verdi, che insistono per ottenere un'esenzione a favore dei pensionati prima di dare il proprio sostegno. Le modifiche, che entrerebbero in vigore da aprile 2027, farebbero risparmiare 3 miliardi di dollari al bilancio federale, ma si stima che circa 80mila anziani australiani abbandonerebbero la copertura sanitaria privata entro il 2028-29 a causa della proposta del governo Albanese. Lo riferisce The Guardian.",
   "more": [
    "In Australia il sistema sanitario combina copertura pubblica universale e assicurazioni private sovvenzionate dallo Stato tramite rimborsi, pensati per alleggerire la pressione sul sistema pubblico. Le proposte di riduzione di tali sussidi sollevano spesso il timore che gli anziani, più bisognosi di cure, abbandonino la copertura privata."
   ],
