   "orig": "does the paris of the impressionists still exist? alix urien finds it through her lens",
   "lead": "Designboom presenta il lavoro della fotografa francese Alix Urien, che nei suoi scatti degli anni 2020 rivisita l'estetica dell'impressionismo, usando movimento, luce e colore per catturare la bellezza fugace di Parigi e della Normandia contemporanee. Lo riferisce Designboom.",
