   "sez": "mondo",
   "titolo": "Il Regno Unito esercita truppe per una possibile riconquista delle Falkland dopo le parole di Milei",
   "orig": "Il Regno Unito teme un attacco dall’Argentina: esercitazioni dei soldati britannici per la riconquista delle Falkland dopo le parole di Milei",
   "lead": "Il Regno Unito avrebbe condotto un'esercitazione militare simulando la riconquista delle Falkland, secondo una rivelazione del Times ripresa da Il Fatto Quotidiano, dopo le recenti rivendicazioni del presidente argentino Javier Milei sulle isole dell'Atlantico del Sud. Si tratterebbe della prima esercitazione di questo tipo dopo molti anni, un segnale politico verso Buenos Aires in un contesto di tensioni rinnovate sulla sovranità dell'arcipelago, oggi sotto controllo britannico ma rivendicato dall'Argentina. Lo riferisce Il Fatto Quotidiano.",
   "more": [
    "Le Falkland (o Malvinas) sono un arcipelago nell'Atlantico del Sud sotto sovranità britannica, da decenni rivendicato dall'Argentina; la disputa portò nel 1982 a una guerra tra i due paesi e resta tuttora oggetto di tensioni diplomatiche."
   ],
