   "titolo": "Mozambico, la comunità di Nsadzu festeggia l'arrivo dell'elettricità con un nuovo impianto solare",
   "orig": "Mozambique: Nsadzu celebrates arrival of electricity as FUNAE commissions solar power plant",
   "lead": "Gli abitanti di Nsadzu, nel distretto di Chifunde, provincia di Tete, in Mozambico, hanno celebrato l'arrivo dell'elettricità grazie all'inaugurazione di un impianto solare realizzato dal Fondo per l'Energia (FUNAE). La nuova infrastruttura energetica apre prospettive di sviluppo per la comunità locale, che per anni ha dovuto affrontare le difficoltà legate alla mancanza di corrente elettrica. L'impianto rappresenta un passo concreto verso l'elettrificazione di aree rurali spesso escluse dalle reti energetiche nazionali. Lo riferisce Club of Mozambique.",
   "more": [
    "Il FUNAE è l'agenzia governativa mozambicana dedicata a promuovere l'accesso all'energia nelle zone rurali, spesso attraverso impianti solari, in un paese dove gran parte della popolazione vive ancora senza collegamento alla rete elettrica nazionale."
   ],
